"""Aggregate actual existing-value availability, keeping original field masks and versions."""
import collections,datetime,hashlib,json,os,sqlite3,time
from pathlib import Path
R=Path.home()/'migration';B=R/'execution_20261116/run001';O=B/'continuation02';P=B/'continuation01/joined_revision003/REUSED_VALUES_WITH_CREATED_PRIVATE.sqlite';os.umask(0o077)
def sha(p):return hashlib.file_digest(p.open('rb'),'sha256').hexdigest()
before=sha(P);start=time.time();db=sqlite3.connect(P.as_uri()+'?mode=ro',uri=True)
report={'at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'known_semantic_ledger_only_not_full_US_population','aggregation_correction':'empty context-only keys excluded from directly bound ad counts; multiple source files are not called multiple review versions; original data unchanged','field_masks':[{'family':f,'original_status':s,'unique_contexts':h,'unique_directly_bound_ad_keys':k,'context_only_mask_rows':empty,'mask_rows':n} for f,s,h,k,n,empty in db.execute('select family,status,count(distinct h),count(distinct nullif(k,"")),count(*),sum(k="") from field_mask group by family,status')],'attached_value_versions':[{'asset':a,'original_accepted':bool(o),'documents':n,'unique_contexts':h} for a,o,n,h in db.execute('select asset,original_accepted,count(*),count(distinct h) from document group by asset,original_accepted')],'stored_value_families':[{'family':f,'original_status':s,'rows':n} for f,s,n in db.execute('select family,status,count(*) from field_value group by family,status')],'known_ad_keys':db.execute('select count(distinct k) from ad').fetchone()[0],'created_join_states':dict(db.execute('select status,count(*) from metadata_resolution group by status')),'original_accepted_ad_keys_with_values':db.execute('select count(distinct k) from accepted_original_values').fetchone()[0],'missing_value_carriers_by_issue':dict(db.execute('select kind,count(*) from issue group by kind')),'contexts_with_multiple_original_accepted_source_files_not_version_count':db.execute('select count(*) from (select h from document where original_accepted=1 group by h having count(distinct source_sha)>1)').fetchone()[0],'new_inference_calls':0,'newly_accepted_records':0,'rules_or_outputs_modified':False,'paper_analysis_started':False}
db.close();assert sha(P)==before
report['input_database_sha256']=before;report['elapsed_seconds']=round(time.time()-start,3)
(O/'REUSE_AVAILABILITY_V2_PUBLIC.json').write_text(json.dumps(report,indent=2)+'\n')
import base64,zlib
enc=base64.b64encode(zlib.compress(json.dumps(report).encode(),9)).decode();assert len(enc)<3600;print(json.dumps({'aggregate_zlib_b64':enc}))
